"""Read-only source snapshot audit. Counts are not verified business identities."""
import argparse, json, hashlib
from pathlib import Path
import duckdb
p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
c=duckdb.connect();c.execute("SET threads=2; SET memory_limit='512MB'")
c.read_parquet(str(a.source)).create_view('records')
def query(sql):
 cur=c.execute(sql); names=[x[0] for x in cur.description];return [dict(zip(names,r)) for r in cur.fetchall()]
fields=[x['column_name'] for x in query('DESCRIBE records')]
missing={f:c.execute('SELECT count(*) FROM records WHERE "'+f+'" IS NULL'+(' OR trim("'+f+'")=\'\'' if f!='sources' and next(x['column_type'] for x in query('DESCRIBE records') if x['column_name']==f)=='VARCHAR' else '')).fetchone()[0] for f in fields}
result={'scope':'Local targeting parquet snapshot only; database tables and upstream source relationships not yet audited','source':str(a.source),'sha256':hashlib.sha256(a.source.read_bytes()).hexdigest(),'totals':query('SELECT count(*) records,count(distinct poi_key) distinct_source_keys,count(*)-count(distinct poi_key) nonunique_or_null_keys FROM records')[0],'missing_counts':missing,'source_distribution':query('SELECT source_name,count(*) records FROM (SELECT unnest(sources) AS source_name FROM records) GROUP BY 1 ORDER BY 2 DESC'),'regions':query('SELECT region_ar,region_en,count(*) records FROM records GROUP BY 1,2 ORDER BY 3 DESC'),'cities':query('SELECT city_ar,city_en,region_ar,count(*) records FROM records GROUP BY 1,2,3 ORDER BY 4 DESC'),'raw_label_counts':query('SELECT count(distinct city_en) city_en,count(distinct city_ar) city_ar,count(distinct district_ar) district_ar,count(distinct district_en) district_en,count(distinct category) category,count(distinct category_l3) category_l3 FROM records')[0],'statuses':query('SELECT company_status,lifecycle_state,count(*) records FROM records GROUP BY 1,2 ORDER BY 3 DESC'),'coordinate_checks':query('SELECT count(*) FILTER (WHERE latitude IS NOT NULL AND (latitude NOT BETWEEN -90 AND 90 OR longitude NOT BETWEEN -180 AND 180)) invalid_global_coordinates,count(*) FILTER (WHERE latitude IS NOT NULL AND longitude IS NULL OR latitude IS NULL AND longitude IS NOT NULL) partial_coordinates FROM records')[0],'evidence_limit':'Source labels, descriptions, websites and source_count do not establish independently verified product sales or purchases. Verified evidence count is NOT MEASURABLE from this snapshot alone.','unique_entities':'NOT ESTIMATED: source-key uniqueness is not business entity uniqueness.'}
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps({'totals':result['totals'],'raw_label_counts':result['raw_label_counts'],'output':str(a.output)},ensure_ascii=False))
